    "type": "Múltipla escolha",
    "isAnulada": false,
    "statement": "A paciente A.F., 27 anos, e seu marido L.O., 30 anos, vêm ao consultório com desejo gestacional. Usuária de contracepção hormonal desde os 18 anos de idade refere ter parado o uso há 1 ano e 6 meses. Desde então manteve ciclos regulares de 26 dias e com boa frequência sexual durante período fértil. A respeito da infertilidade, considere as seguintes afirmativas: 1. A endometriose, que tem como causa principal as aderências causadas e possível obstrução ou falha de função tubária, é uma doença multifatorial que pode levar à infertilidade. 2. Apesar do tabagismo ser associado com diferentes intercorrências na saúde do usuário, ele não tem relação direta com a infertilidade comprovada. 3. Fatores externos, como uma boa qualidade de vida com exercícios físicos, boa alimentação e boas noites de sono, são cruciais para o bom desenvolvimento do oócito e do espermatozoide. 4. Durante a investigação inicial de infertilidade, os exames necessários são: hormonais (FSH, LH, estradiol, progesterona, prolactina, TSH, T4l, testosterona livre, testosterona total, S-Dhea); imagem (ecografia transvaginal, histerossalpingografia); fator masculino (espermograma, ecografia bolsa escrotal e doppler de testículo). Assinale a alternativa correta.",
