    "statement": "Paciente, 35 anos de idade, nuligesta, vem ao consultório para consulta de rotina e introdução de método contraceptivo. Teve menarca aos 14 anos de idade, ciclos menstruais regulares, com fluxo sanguíneo baixo, durando quatro dias. Refere dismenorreia intensa desde que parou de usar anticoncepcional, há um ano, necessitando, por muitas vezes, de medicação venosa para controle da dor. Apresentou um episódio de síncope, neste ano, durante momento de dor intensa. Nega comorbidades ou cirurgias prévias. A paciente trouxe ultrassonografia transvaginal atual evidenciando útero em Antero Verso Flexão, com volume de 72 cm³, com ecotextura de miométrio homogênea. Em fundo uterino, nota-se nódulo hipoecoico, bem delimitado, subseroso, pediculado de 3,5 cm x 2,9 cm. Linha endometrial homogênea de 5 mm, ovário direito de 4,5 cm³ e ovário esquerdo de 7,5 cm³. Citologia vaginal: negativa para neoplasia com inflamação discreta e Candida allbicans. A paciente retorna após quatro anos, com o esposo, referindo dificuldade para engravidar, não usa método contraceptivo há um ano e meio; exames complementares mostram espermograma do cônjuge com concentração de 23 milhões de espermatozoides/ml de sêmen; motilidade: A+B = 32%, morfologia; 4% de normalidade (morfologia Kruger), histerossalpingografia da paciente; obstrução tubária proximal bilateral. Frente a esse quadro, indique o exame padrão-ouro para diagnóstico na primeira consulta.",
