    "type": "Múltipla escolha",
    "isAnulada": true,
    "statement": "A resolução n.º 2013/ 2013 do Conselho Federal de Medicina visa a adotar as normas éticas para a utilização das técnicas de reprodução assistida, como dispositivo deontológico a ser seguido pelos médicos. Essa resolução determina algumas normativas. Analise os itens a seguir, marque verdadeiro (V) ou falso (F) e assinale a alternativa CORRETA. (   ) A idade máxima das candidatas à gestação de reprodução assistida é de 50 anos. (   ) As técnicas de reprodução assistida não podem ser aplicadas com a intenção de selecionar o sexo (presença ou ausência de cromossomo Y) ou qualquer outra característica biológica do futuro filho, exceto quando se trate de evitar doenças ligadas ao sexo do filho que venha a nascer. (   ) Quanto ao número de embriões a serem transferidos, faz-se a seguinte recomendação: nas mulheres com até 35 anos – até quatro embriões. (   ) Em caso de gravidez múltipla, decorrente do uso de técnicas de reprodução assistida, é permitida a utilização de procedimentos que visem à redução embrionária, nos casos que tenham mais de 03 (três) embriões implantados. (   ) É permitido o uso das técnicas de reprodução assistida para relacionamentos homoafetivos e pessoas solteiras, não respeitado o direito da objeção de consciência do médico.",
